import { Router } from 'express';
import { randomUUID } from 'node:crypto';
import { fail, route } from './errors.js';
import { totals } from './cart.js';
import { discountFor } from './discounts.js';
export function checkoutRoutes(store,carts) {
  const router=Router();
  router.post('/checkout',route(async(req,res)=>{
    const {cartId,email}=req.body;
    if(typeof cartId!=='string'||typeof email!=='string'||!email.includes('@'))fail(400,'INVALID_INPUT','cartId and an email containing @ are required');
    const order=await store.exclusive(async()=>{
      const cart=carts.get(cartId);if(!cart.items.length)fail(409,'EMPTY_CART','Cart is empty');
      const products=await store.read('products');
      const short=cart.items.filter(line=>{const p=products.find(p=>p.id===line.productId);return !p||p.stock<line.quantity;});
      if(short.length)fail(409,'OUT_OF_STOCK','Insufficient stock: '+short.map(line=>products.find(p=>p.id===line.productId)?.name||line.productId).join(', '));
      const items=cart.items.map(line=>{const p=products.find(p=>p.id===line.productId);return {productId:p.id,name:p.name,priceCents:p.priceCents,quantity:line.quantity};});
      const subtotal=items.reduce((sum,line)=>sum+line.priceCents*line.quantity,0);
      const discount=await discountFor(store,cart.discountCode,subtotal,true);
      const order={id:randomUUID(),cartId,items,...totals(subtotal,discount),discountCode:cart.discountCode,createdAt:new Date().toISOString()};
      const orders=await store.read('orders');
      for(const line of cart.items)products.find(p=>p.id===line.productId).stock-=line.quantity;
      await store.write('products',products);await store.write('orders',[...orders,order]);
      cart.items=[];cart.discountCode=null;return order;
    });
    res.status(201).json(order);
  }));
  return router;
}

